INSERT OR REPLACE INTO cards (id, name, name_cn, name_jp, type, race, attribute, level, atk, def, desc_cn) VALUES
(49161188, 'Gilti-Gearfried the Magical Steel Knight', '钢铁魔导骑士-基尔提基亚·弗里德', '鋼鉄の魔導騎士－ギルティギア・フリード', 'Fusion Monster', 'Warrior', 'LIGHT', 8, 2700, 1600, '属性不同的战士族怪兽×2 ①：1回合1次，这张卡为对象的魔法·陷阱·怪兽的效果发动时才能发动。那个效果无效，选场上1张卡破坏。 ②：只用场上的怪兽为素材作融合召唤的这张卡在同1次的战斗阶段中可以作2次攻击。 ③：1回合1次，这张卡和对方怪兽进行战斗的伤害计算时，从自己墓地把1张魔法卡除外才能发动。这张卡的攻击力直到回合结束时上升这张卡的守备力一半数值。'),
(51828629, 'Giltia the D. Knight', '魔导骑士 基尔提亚', '魔導騎士ギルティア', 'Fusion Monster', 'Warrior', 'LIGHT', 5, 1850, 1500, '「冥界的番人」＋「王座守护者」'),
(77406972, 'Giltia the D. Knight - Soul Spear', '魔导骑士 基尔提亚-灵魂之枪', '魔導騎士ギルティア－ソウル・スピア', 'Effect Monster', 'Warrior', 'LIGHT', 5, 1850, 1500, '这个卡名的③的效果1回合只能使用1次。 ①：自己场上没有怪兽存在的场合，这张卡可以不用解放作召唤。 ②：这张卡召唤成功时才能发动。选持有这张卡的攻击力以上的攻击力的对方场上1只怪兽除外。 ③：丢弃1张手卡才能发动。从卡组把以下怪兽之内1只加入手卡。 ●龙族·暗属性·7星怪兽 ●机械族·暗属性·6星怪兽 ●战士族·水属性·5星怪兽'),
(79086452, 'Gimmick Puppet Bisque Doll', '机关傀偶－素瓷娃娃', 'ギミック・パペット－ビスク・ドール', 'Effect Monster', 'Machine', 'DARK', 8, 1000, 1000, '①：这张卡可以把手卡1只「机关傀儡」怪兽丢弃，从手卡特殊召唤。 ②：把墓地的这张卡除外才能发动。这个回合中，对方不能把自己场上的「机关傀儡」怪兽作为效果的对象。'),
(99229085, 'Gimmick Puppet Cattle Scream', '机关傀偶－牛啸', 'ギミック・パペット－カトル・スクリーム', 'Effect Monster', 'Machine', 'DARK', 8, 2000, 2000, '这个卡名的①的效果1回合只能使用1次。 ①：把自己场上1个超量素材取除才能发动。这张卡从手卡·墓地特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。 ②：持有这张卡作为素材中的「机关傀儡」超量怪兽得到以下效果。 ●1回合1次，以对方墓地1只怪兽为对象才能发动。那只怪兽在对方场上守备表示特殊召唤。'),
(97520532, 'Gimmick Puppet Chimera Doll', '机关傀偶－奇美拉娃娃', 'ギミック・パペット－キメラ・ドール', 'Link Monster', 'Machine', 'DARK', NULL, 1500, NULL, '机械族怪兽2只 这个卡名的效果1回合只能使用1次。 ①：这张卡是已连接召唤的场合才能发动。从卡组选1只「机关傀儡」怪兽加入手卡或送去墓地。自己场上的怪兽只有「机关傀儡」怪兽的场合，可以再从手卡把1只「机关傀儡」怪兽特殊召唤。这个效果的发动后，直到回合结束时自己不是机械族超量怪兽不能从额外卡组特殊召唤。'),
(76543119, 'Gimmick Puppet Des Troy', '机关傀儡-死之木马', 'ギミック・パペット－死の木馬', 'Effect Monster', 'Machine', 'DARK', 4, 1200, 2000, '①：只在这张卡在场上表侧表示存在才有1次，以场上1只「机关傀儡」怪兽为对象才能发动。那只怪兽破坏。 ②：这张卡从场上送去墓地时才能发动。从手卡把最多2只「机关傀儡」怪兽特殊召唤。'),
(92418590, 'Gimmick Puppet Dreary Doll', '机关傀偶－死灵娃娃', 'ギミック・パペット－ネクロ・ドール', 'Effect Monster', 'Machine', 'DARK', 8, NULL, NULL, '这个卡名的效果1回合只能使用1次，把这张卡作为超量召唤的素材的场合，不是「机关傀儡」怪兽的超量召唤不能使用。 ①：这张卡在墓地存在的场合，从自己墓地把这张卡以外的1只「机关傀儡」怪兽除外才能发动。这张卡特殊召唤。'),
(20032555, 'Gimmick Puppet Egg Head', '机关傀儡-炸蛋头', 'ギミック・パペット－ボム・エッグ', 'Effect Monster', 'Machine', 'EARTH', 4, 1600, 1200, '自己的主要阶段时可以从手卡丢弃1只名字带有「机关傀儡」的怪兽，从以下效果选择1个发动。「机关傀儡-炸蛋头」的效果1回合只能使用1次。 ●给与对方基本分800分伤害。 ●这张卡的等级直到结束阶段时变成8星。'),
(76290637, 'Gimmick Puppet Fantasix Machinix', '机关傀偶－迷魅机械神', 'ギミック・パペット－ファンタジクス・マキナ', 'XYZ Monster', 'Machine', 'DARK', 8, 1500, 3100, '8星怪兽×2 这个卡名的①②的效果1回合各能使用1次。 ①：把这张卡1个超量素材取除才能发动。从卡组把1张「升阶魔法」魔法卡加入手卡。这个回合，自己在通常召唤外加上只有1次，自己主要阶段可以把1只机械族怪兽召唤。 ②：自己把「机关傀儡」超量怪兽特殊召唤的场合才能发动。这张卡从墓地往自己或对方的场上守备表示特殊召唤。那之后，可以从自己墓地把1张「升阶魔法」魔法卡加入手卡。'),
(4145915, 'Gimmick Puppet Fiendish Knight', '机关傀偶－杀手骑士', 'ギミック・パペット－キラーナイト', 'Effect Monster', 'Machine', 'DARK', 4, 1800, 500, '这个卡名的①②的效果1回合各能使用1次，这些效果发动的回合，自己不是「机关傀儡」怪兽不能从额外卡组特殊召唤。 ①：这张卡在手卡存在的场合，以自己墓地1只「机关傀儡」怪兽或者对方墓地1只怪兽为对象才能发动。那只怪兽在持有者场上效果无效守备表示特殊召唤。那之后，这张卡特殊召唤。 ②：这张卡从手卡以外送去墓地的场合才能发动。这张卡加入手卡。'),
(56427559, 'Gimmick Puppet Gear Changer', '机关傀儡-齿轮变速者', 'ギミック・パペット－ギア・チェンジャー', 'Effect Monster', 'Machine', 'EARTH', 1, 100, 100, '这张卡不能从卡组特殊召唤。1回合1次，选择这张卡以外的自己场上1只名字带有「机关傀儡」的怪兽才能发动。这张卡的等级变成和选择的怪兽的等级相同。'),
(7593748, 'Gimmick Puppet Gigantes Doll', '机关傀偶－癸干忒斯娃娃', 'ギミック・パペット－ギガンテス・ドール', 'XYZ Monster', 'Machine', 'DARK', 4, NULL, 2000, '4星「机关傀儡」怪兽×2 这个卡名的①②的效果1回合各能使用1次。 ①：把这张卡2个超量素材取除，以对方场上最多2只怪兽为对象才能发动。那些怪兽的控制权直到结束阶段得到。这个效果的发动后，直到回合结束时自己不是「机关傀儡」怪兽不能特殊召唤，不用超量怪兽不能攻击宣言。 ②：把这张卡解放才能发动。自己场上的全部怪兽的等级直到回合结束时变成8星。'),
(8226374, 'Gimmick Puppet Humpty Dumpty', '机关傀儡-小矮蛋', 'ギミック・パペット－ハンプティ・ダンプティ', 'Effect Monster', 'Machine', 'DARK', 4, NULL, 100, '这个卡名的效果1回合只能使用1次。 ①：这张卡召唤·特殊召唤成功时才能发动。从手卡把1只「机关傀儡」怪兽特殊召唤。'),
(36436372, 'Gimmick Puppet Little Soldiers', '机关傀偶－小兵队', 'ギミック・パペット－リトル・ソルジャーズ', 'Effect Monster', 'Machine', 'DARK', 4, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：这张卡召唤·特殊召唤的场合，把和这张卡等级不同的1只「机关傀儡」怪兽从卡组送去墓地才能发动。这张卡的等级变成和送去墓地的怪兽相同。 ②：把墓地的这张卡除外，以自己场上最多2只「机关傀儡」怪兽为对象才能发动。那些怪兽的等级直到回合结束时上升4星。'),
(39806198, 'Gimmick Puppet Magnet Doll', '机关傀儡-磁力人偶', 'ギミック・パペット－マグネ・ドール', 'Effect Monster', 'Machine', 'DARK', 8, 1000, 1000, '①：对方场上有怪兽存在，自己场上的怪兽只有「机关傀儡」怪兽的场合，这张卡可以从手卡特殊召唤。'),
(55204071, 'Gimmick Puppet Nightmare', '机关傀偶－梦魇', 'ギミック・パペット－ナイトメア', 'Effect Monster', 'Machine', 'DARK', 8, 1000, 2000, '这张卡可以把自己场上表侧表示存在的1只超量怪兽解放从手卡特殊召唤。这个方法的「机关傀儡-梦魇」的特殊召唤1回合只能有1次。这个方法特殊召唤成功时，可以从自己的手卡·墓地选1只「机关傀儡-梦魇」特殊召唤。此外，这张卡特殊召唤成功的回合，自己不能把名字带有「机关傀儡」的怪兽以外的怪兽特殊召唤。'),
(63825486, 'Gimmick Puppet Rouge Doll', '机关傀偶－血腥娃娃', 'ギミック・パペット－ブラッディ・ドール', 'Effect Monster', 'Machine', 'DARK', 8, 400, 1400, '这个卡名的①②的效果1回合各能使用1次，这些效果发动的回合，自己不是「机关傀儡」怪兽不能从额外卡组特殊召唤。 ①：这张卡在手卡存在的场合，把额外卡组1只「机关傀儡」超量怪兽给对方观看才能发动。把持有和给人观看的怪兽的阶级相同数值的等级的卡组1只「机关傀儡」怪兽和这张卡特殊召唤。 ②：这张卡从手卡以外送去墓地的场合才能发动。这张卡加入手卡。'),
(29216967, 'Gimmick Puppet Scissor Arms', '机关傀偶－剪刀臂', 'ギミック・パペット－シザー・アーム', 'Effect Monster', 'Machine', 'DARK', 4, 1200, 600, '①：这张卡召唤时才能发动。从卡组把1只「机关傀儡」怪兽送去墓地。'),
(34620088, 'Gimmick Puppet Shadow Feeler', '机关傀儡-暗影触摸者', 'ギミック・パペット－シャドーフィーラー', 'Effect Monster', 'Machine', 'DARK', 8, 1000, 1000, '这张卡不会被战斗破坏。此外，这张卡在墓地存在，对方怪兽的直接攻击让自己受到战斗伤害时才能发动。这张卡从墓地表侧攻击表示特殊召唤，自己受到1000分伤害。「机关傀儡-暗影触摸者」的这个效果1回合只能使用1次。成为超量素材的这张卡被送去墓地的场合，不去墓地从游戏中除外。'),
(43598843, 'Gimmick Puppet Terror Baby', '机关傀偶－恐怖婴', 'ギミック・パペット－テラー・ベビー', 'Effect Monster', 'Machine', 'DARK', 4, 500, NULL, '①：这张卡召唤成功时，以「机关傀儡-恐怖婴儿」以外的自己墓地1只「机关傀儡」怪兽为对象才能发动。那只怪兽守备表示特殊召唤。 ②：把墓地的这张卡除外才能发动。这个回合，对方不能对应自己的「机关傀儡」怪兽的效果的发动把魔法·陷阱·怪兽的效果发动。'),
(92821268, 'Gimmick Puppet Twilight Joker', '机关傀儡-夜小丑', 'ギミック・パペット－ナイト・ジョーカー', 'Effect Monster', 'Machine', 'DARK', 8, 800, 1600, '自己场上的名字带有「机关傀儡」的怪兽被战斗破坏送去自己墓地时，把那只怪兽从游戏中除外才能发动。这张卡从手卡特殊召唤。「机关傀儡-夜小丑」的效果1回合只能使用1次。'),
(79922118, 'Gingerbread House', '糖果屋', 'おかしの家', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：对方准备阶段才能发动。对方场上的全部怪兽的攻击力上升600。那之后，对方场上的攻击力2500以上的怪兽全部破坏，自己回复破坏的怪兽数量×500基本分。'),
(84620194, 'Girochin Kuwagata', '断头台锹甲', 'ギロチン・クワガタ', 'Normal Monster', 'Insect', 'WIND', 4, 1700, 1000, '栖息在精灵之森的甲虫，虽不过人的大拇指一般大，但却有着连钢铁都能咬断的下颚。'),
(69811710, 'Girsu, the Orcust Mekk-Knight', '宵星之自鸣天琴・机界骑士', '宵星の騎士ギルス', 'Effect Monster', 'Machine', 'DARK', 4, 1800, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。从卡组把1张「自奏圣乐」卡或「星遗物」卡送去墓地。和这张卡相同纵列有其他卡2张以上存在的场合，再在这个回合把这张卡当作调整使用。 ②：自己场上没有其他怪兽存在的场合才能发动。在双方场上把「星遗物衍生物」（机械族·暗·1星·攻/守0）各1只守备表示特殊召唤。'),
(67111213, 'Gishki Abyss', '咒仪・邃渊', 'リチュア・アビス', 'Effect Monster', 'Fish', 'WATER', 2, 800, 500, '①：这张卡召唤·反转召唤·特殊召唤成功时才能发动。从卡组把「遗式深渊鲛」以外的1只守备力1000以下的「遗式」怪兽加入手卡。'),
(46159582, 'Gishki Aquamirror', '咒仪之仪水镜', 'リチュアの儀水鏡', 'Spell Card', 'Ritual', NULL, NULL, NULL, NULL, '「遗式」仪式怪兽的降临必需。 ①：等级合计直到变成和仪式召唤的怪兽相同为止，把自己的手卡·场上的怪兽解放，从手卡把1只「遗式」仪式怪兽仪式召唤。 ②：让墓地的这张卡回到卡组，以自己墓地1只「遗式」仪式怪兽为对象才能发动。那只怪兽加入手卡。'),
(92784374, 'Gishki Ariel', '咒仪・艾莉娅儿', 'リチュア・エリアル', 'Flip Effect Monster', 'Spellcaster', 'WATER', 4, 1000, 1800, '反转：可以从卡组把1只名字带有「遗式」的怪兽加入手卡。'),
(16693254, 'Gishki Avance', '咒仪・阿凡斯', 'リチュア・アバンス', 'Effect Monster', 'Spellcaster', 'WATER', 4, 1500, 800, '1回合1次，可以从自己卡组选择1只名字带有「遗式」的怪兽在卡组最上面放置。'),
(36227804, 'Gishki Beast', '咒仪・野兽', 'リチュア・ビースト', 'Effect Monster', 'Beast', 'WATER', 4, 1500, 1300, '这张卡召唤成功时，可以选择自己墓地存在的1只4星以下的名字带有「遗式」的怪兽表侧守备表示特殊召唤。'),
(66399675, 'Gishki Chain', '咒仪・锁链', 'リチュア・チェイン', 'Effect Monster', 'Sea Serpent', 'WATER', 4, 1800, 1000, '这张卡召唤成功时，从卡组上面把3张卡确认。确认的卡之中有仪式怪兽或者仪式魔法卡的场合，可以把那1张给对方观看并加入手卡。那之后，确认的卡用喜欢的顺序回到卡组上面。'),
(72403299, 'Gishki Diviner', '咒仪・占卜师', 'リチュア・ディバイナー', 'Effect Monster', 'Sea Serpent', 'WATER', 3, 1200, 800, '1回合1次，宣言1个卡名才能发动。把自己卡组最上面的卡翻开，那是宣言的卡的场合加入手卡。不是的场合，回到自己卡组最上面。'),
(73551138, 'Gishki Emilia', '咒仪・艾米莉娅', 'リチュア・エミリア', 'Spirit Monster', 'Spellcaster', 'WATER', 4, 1600, 800, '这张卡不能特殊召唤。召唤·反转的回合的结束阶段时回到持有者手卡。这张卡召唤·反转时，自己场上有这张卡以外的名字带有「遗式」的怪兽存在的场合，直到结束阶段时场上的陷阱卡的效果无效。'),
(38356857, 'Gishki Grimness', '残虐・咒仪', 'グリム・リチュア', 'Effect Monster', 'Fish', 'WATER', 2, 600, 700, '这个卡名的②的效果1回合只能使用1次。 ①：水属性仪式怪兽1只仪式召唤的场合，可以用这1张卡作为仪式召唤需要的数值的解放使用。 ②：这张卡召唤·特殊召唤成功的场合才能发动。从卡组把「冷酷遗式术师」以外的1只「遗式」怪兽特殊召唤。这个效果的发动后，直到回合结束时自己不用仪式怪兽不能攻击宣言。'),
(39905966, 'Gishki Marker', '遗式纹身者', 'リチュア・マーカー', 'Effect Monster', 'Aqua', 'WATER', 4, 1600, 1200, '这张卡召唤·反转召唤·特殊召唤成功时，可以选择名字带有「遗式」的自己墓地存在的1张仪式怪兽或者仪式魔法卡加入手卡。'),
(19959742, 'Gishki Mollusk', '遗式贝', 'リチュア・シェルフィッシュ', 'Effect Monster', 'Aqua', 'WATER', 4, 1700, 900, '这张卡被卡的效果送去墓地时，从自己卡组上面把3张卡确认，确认的3张用喜欢的顺序回到卡组上面或下面。'),
(17241370, 'Gishki Natalia', '咒仪・娜塔莉亚', 'リチュア・ナタリア', 'Spirit Monster', 'Spellcaster', 'WATER', 4, 1800, 900, '这张卡不能特殊召唤。召唤·反转的回合的结束阶段时回到持有者手卡。这张卡召唤·反转时，可以选择自己墓地1只名字带有「遗式」的怪兽回到卡组最上面。'),
(36982581, 'Gishki Nekromirror', '咒仪之冰魔镜', 'リチュアの氷魔鏡', 'Spell Card', 'Ritual', NULL, NULL, NULL, NULL, '「遗式」仪式怪兽的降临必需。 ①：对方场上1只表侧表示怪兽解放或者等级合计直到变成和仪式召唤的怪兽相同为止把自己的手卡·场上的怪兽解放，从手卡把1只「遗式」仪式怪兽仪式召唤，自己失去那个原本攻击力数值的基本分。 ②：这张卡在墓地存在的场合，以自己墓地1只「遗式」怪兽为对象才能发动。那只怪兽回到卡组最上面，这张卡回到卡组最下面。'),
(63942761, 'Gishki Noellia', '咒仪・诺艾莉娅', 'リチュア・ノエリア', 'Effect Monster', 'Spellcaster', 'WATER', 4, 1700, 1000, '这张卡召唤成功时，可以从自己卡组上面把5张卡翻开。翻开的卡之中有仪式魔法卡或者名字带有「遗式」的怪兽卡的场合，那些卡全部送去墓地。剩下的卡用喜欢的顺序回到卡组最下面。'),
(9236985, 'Gishki Photomirror', '咒仪之写魂镜', 'リチュアの写魂鏡', 'Spell Card', 'Ritual', NULL, NULL, NULL, NULL, '名字带有「遗式」的仪式怪兽的降临必需。必须支付仪式召唤的怪兽等级×500基本分。'),
(30334522, 'Gishki Psychelone', '禁咒仪・精神鳌魔', 'イビリチュア・プシュケローネ', 'Ritual Effect Monster', 'Fiend', 'WATER', 4, 2150, 1650, '名字带有「遗式」的仪式魔法卡降临。1回合1次，宣言怪兽的种族·属性才能发动。把对方手卡随机1张确认，宣言的种族·属性的怪兽的场合，那张卡回到持有者卡组。不是的场合回到原状。'),
(37557626, 'Gishki Reliever', '遗式杀手', 'リチュア・キラー', 'Effect Monster', 'Aqua', 'WATER', 2, 500, 800, '这张卡召唤·反转召唤成功时，自己场上有这张卡以外的名字带有「遗式」的怪兽表侧表示存在的场合，可以选择这张卡以外的自己场上存在的1只怪兽回到手卡。'),
(29888389, 'Gishki Shadow', '暗影・咒仪', 'シャドウ・リチュア', 'Effect Monster', 'Sea Serpent', 'WATER', 4, 1200, 1000, '①：水属性仪式怪兽1只仪式召唤的场合，可以用这1张卡作为仪式召唤需要的数值的解放使用。 ②：把这张卡从手卡丢弃才能发动。从卡组把1张「遗式」仪式魔法卡加入手卡。'),
(93506862, 'Gishki Vanity', '遗式虚巫 瓦尼蒂', 'リチュア・ヴァニティ', 'Effect Monster', 'Aqua', 'WATER', 2, 1000, 800, '自己的主要阶段时，把这张卡从手卡丢弃才能发动。这个回合，对方不能对应名字带有「遗式」的仪式魔法卡的发动把魔法·陷阱·效果怪兽的效果发动，名字带有「遗式」的仪式怪兽仪式召唤成功时，对方不能把魔法·陷阱·效果怪兽的效果发动。'),
(47106439, 'Gishki Vision', '幻影・咒仪', 'ヴィジョン・リチュア', 'Effect Monster', 'Sea Serpent', 'WATER', 2, 700, 500, '①：水属性仪式怪兽1只仪式召唤的场合，可以用这1张卡作为仪式召唤需要的数值的解放使用。 ②：把这张卡从手卡丢弃才能发动。从卡组把1只「遗式」仪式怪兽加入手卡。'),
(66729231, 'Gishki Zielgigas', '禁咒仪・魂魄巨人', 'イビリチュア・ジールギガス', 'Ritual Effect Monster', 'Aqua', 'WATER', 10, 3200, NULL, '名字带有「遗式」的仪式魔法卡降临。1回合1次，支付1000基本分才能发动。从卡组抽1张卡，给双方确认。确认的卡是名字带有「遗式」的怪兽的场合，场上1张卡回到持有者卡组。'),
(55465441, 'Give and Take', '平等交换', 'ギブ＆テイク', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己墓地1只怪兽和自己场上1只表侧表示怪兽为对象才能发动。作为对象的墓地的怪兽在对方场上守备表示特殊召唤，作为对象的场上的怪兽的等级直到回合结束时上升那只特殊召唤的怪兽的等级数值。'),
(59789370, 'Gizmek Arakami, the Hailbringer Hog', '机巧猪－伊服岐雹荒神', '機巧猪－伊服岐雹荒神', 'Effect Monster', 'Machine', 'WATER', 4, 1850, 1850, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上有攻击力和守备力的数值相同的机械族怪兽存在的场合才能发动。这张卡从手卡特殊召唤。 ②：把墓地的这张卡除外，以自己场上1只攻击力和守备力的数值相同的机械族怪兽为对象才能发动。攻击力和守备力的数值相同而持有比作为对象的怪兽低的等级的1只机械族怪兽从卡组送去墓地。作为对象的怪兽的攻击力·守备力上升送去墓地的怪兽的等级×100。'),
(50901852, 'Gizmek Inaba, the Hopping Hare of Hakuto', '机巧兔－稻羽之淤岐素', '機巧菟－稻羽之淤岐素', 'Effect Monster', 'Machine', 'WIND', 1, 50, 50, '这个卡名的②的效果1回合只能使用1次。 ①：这张卡召唤成功时才能发动。攻击力和守备力的数值相同的1只机械族怪兽从手卡守备表示特殊召唤。 ②：把墓地的这张卡除外，以自己场上1只攻击力和守备力的数值相同的机械族怪兽为对象才能发动。这个回合，自己不用那只怪兽不能攻击宣言，那只怪兽的攻击力·守备力变成自己场上的攻击力和守备力的数值相同的机械族怪兽的原本攻击力合计数值。'),
(63633694, 'Gizmek Kaku, the Supreme Shining Sky Stag', '机巧蹄－天迦久御雷', '機巧蹄－天迦久御雷', 'Effect Monster', 'Machine', 'FIRE', 9, 2750, 2750, '这个卡名的①②③的效果1回合各能使用1次。 ①：额外怪兽区域有怪兽存在的场合才能发动。这张卡从手卡特殊召唤。 ②：以额外怪兽区域1只表侧表示怪兽为对象才能发动。那只表侧表示怪兽当作装备卡使用给这张卡装备（只有1只可以装备）。 ③：这张卡战斗破坏对方怪兽时才能发动。选给这张卡装备的1张自己的怪兽卡特殊召唤。'),
(46809548, 'Gizmek Makami, the Ferocious Fanged Fortress', '机巧牙－御神尊真神', '機巧牙－御神尊真神', 'Effect Monster', 'Machine', 'WIND', 6, 2150, 2150, '这个卡名的②③的效果1回合各能使用1次。 ①：除外的自己的卡是6张以上的场合，这张卡可以不用解放作召唤。 ②：这张卡召唤·特殊召唤成功的场合，从手卡丢弃1只怪兽才能发动。从卡组把「机巧牙-御神尊真神」以外的1只攻击力和守备力的数值相同的怪兽加入手卡。 ③：怪兽区域的这张卡被破坏的场合才能发动。选除外的6张自己的卡回到卡组。'),
(96399967, 'Gizmek Naganaki, the Sunrise Signaler', '机巧鸟－常世宇受卖长鸣', '機巧鳥－常世宇受賣長鳴', 'Effect Monster', 'Machine', 'LIGHT', 2, 950, 950, '这个卡名的①②的效果1回合各能使用1次。 ①：把自己场上1只攻击力和守备力的数值相同的机械族怪兽解放才能发动。攻击力和守备力的数值相同而持有比解放的怪兽低的等级的1只机械族怪兽从卡组特殊召唤。 ②：把墓地的这张卡除外才能发动。从里侧表示除外的自己的卡之中选攻击力和守备力的数值相同的1只机械族怪兽加入手卡。'),
(43218406, 'Gizmek Okami, the Dreaded Deluge Dragon', '机巧辰－高暗御津羽靇', '機巧辰－高闇御津羽靇', 'Effect Monster', 'Machine', 'WATER', 10, 2950, 2950, '这个卡名的①③的效果1回合各能使用1次。 ①：从额外卡组特殊召唤的怪兽在场上有2只以上存在的场合才能发动。这张卡从手卡特殊召唤。 ②：支付1500基本分才能发动。从额外卡组特殊召唤的场上的怪兽全部破坏。这个回合，自己只能用1只怪兽攻击。 ③：这张卡被对方送去墓地的场合才能发动。选对方墓地1只怪兽除外。那之后，自己基本分回复那个攻击力的数值。'),
(71197066, 'Gizmek Orochi, the Serpentron Sky Slasher', '机巧蛇－丛云远吕智', '機巧蛇－叢雲遠呂智', 'Effect Monster', 'Machine', 'DARK', 8, 2450, 2450, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：这张卡在手卡·墓地存在的场合，从自己卡组上面把8张卡里侧表示除外才能发动。这张卡特殊召唤。这个效果在对方回合也能发动。 ②：从额外卡组把3张卡里侧表示除外，以场上1只表侧表示怪兽为对象才能发动。那只怪兽破坏。'),
(23384666, 'Gizmek Taniguku, the Immobile Intellect', '机巧蛙－磐盾多迩具久', '機巧蛙－磐盾多邇具久', 'Effect Monster', 'Machine', 'EARTH', 3, 1450, 1450, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。从卡组选攻击力和守备力的数值相同的1只机械族怪兽在卡组最上面放置。 ②：把墓地的这张卡除外，以攻击力和守备力的数值相同的自己墓地1只机械族怪兽为对象才能发动。那只怪兽守备表示特殊召唤。'),
(90361289, 'Gizmek Uka, the Festive Fox of Fecundity', '机巧狐－宇迦之御魂稻荷', '機巧狐－宇迦之御魂稲荷', 'Effect Monster', 'Machine', 'EARTH', 7, 2250, 2250, '这个卡名的①②的效果1回合各能使用1次。 ①：从卡组有怪兽特殊召唤的场合才能发动。这张卡从手卡特殊召唤。 ②：这张卡召唤·特殊召唤成功的场合，以对方场上1只表侧表示怪兽为对象才能发动。从手卡·卡组把攻击力和守备力的数值相同而属性是和作为对象的怪兽相同的1只怪兽特殊召唤。 ③：每次对方对怪兽的召唤·特殊召唤成功发动。给与对方300伤害。'),
(13224603, 'Gizmek Yata, the Gleaming Vanguard', '机巧嘴－八咫御先', '機巧嘴－八咫御先', 'Effect Monster', 'Machine', 'LIGHT', 5, 2050, 2050, '这个卡名的②③的效果1回合各能使用1次。 ①：这张卡可以把自己场上1只通常召唤的怪兽解放从手卡特殊召唤。 ②：这张卡召唤·特殊召唤成功的回合的自己主要阶段才能发动。把1只怪兽召唤。自己在这个效果召唤过的回合，不是原本种族和那只怪兽相同的怪兽不能特殊召唤。 ③：这张卡的①的方法特殊召唤的这张卡被解放的场合发动。自己回复2050基本分。'),
(43175027, 'Glacial Beast Blizzard Wolf', '极冰兽 雪暴狼', '極氷獣ブリザード・ウルフ', 'Effect Monster', 'Aqua', 'WATER', 4, 1400, 700, '这个卡名的①②的效果1回合各能使用1次。 ①：自己或者对方的怪兽的攻击宣言时才能发动。那次攻击无效，从手卡把「极冰兽 雪暴狼」以外的1只4星以下的水属性怪兽特殊召唤。 ②：这张卡在墓地存在，自己场上没有怪兽存在的场合，对方战斗阶段开始时才能发动。这张卡攻击表示特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。'),
(6568731, 'Glacial Beast Iceberg Narwhal', '极冰兽 冰山一角鲸', '極氷獣アイスバーグ・ナーワル', 'Synchro Monster', 'Aqua', 'WATER', 7, 2700, 1600, '调整＋调整以外的水属性怪兽1只以上 这个卡名的②的效果1回合只能使用1次。 ①：每次自己场上的其他怪兽被对方怪兽的攻击或者对方的效果破坏发动。给与对方600伤害。 ②：自己场上有其他怪兽存在，自己·对方的战斗阶段对方把魔法·陷阱·怪兽的效果发动时才能发动。那个效果无效并破坏。'),
(79169622, 'Glacial Beast Polar Penguin', '极冰兽 极地企鹅', '極氷獣ポーラ・ペンギン', 'Tuner Monster', 'Aqua', 'WATER', 3, 800, 1000, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：这张卡特殊召唤成功的场合，以对方场上1只怪兽为对象才能发动。那只怪兽回到持有者手卡。 ②：场上的这张卡被战斗·效果破坏的场合，以对方场上1张卡为对象才能发动。那张卡回到持有者手卡。'),
(11449436, 'Glacier Aqua Madoor', '冰河之水魔道士', '氷河のアクア・マドール', 'Effect Monster', 'Spellcaster', 'WATER', 6, 1200, 3000, '①：自己的通常怪兽和对方怪兽进行战斗的伤害步骤开始时，把手卡的这张卡给对方观看才能发动。选自己1张手卡丢弃，那只自己怪兽不会被那次战斗破坏。 ②：这张卡和对方怪兽进行战斗的伤害步骤开始时，把手卡1只通常怪兽给对方观看才能发动。选自己1张手卡丢弃，那只对方怪兽破坏。'),
(42592719, 'Gladiator Beast Alexander', '剑斗兽 亚历山大', '剣闘獣アレクサンデル', 'Effect Monster', 'Beast', 'LIGHT', 6, 2400, 600, '「剑斗兽 双斗」以外的效果不能把这张卡特殊召唤。特殊召唤的这张卡只要在自己场上表侧表示存在，不受魔法的效果的影响。这张卡进行战斗的战斗阶段结束时可以让这张卡回到卡组，从卡组把「剑斗兽 亚历山大」以外的1只名字带有「剑斗兽」的怪兽在自己场上特殊召唤。'),
(3779662, 'Gladiator Beast Andabata', '剑斗兽 盲剑', '剣闘獣アンダバタエ', 'Fusion Monster', 'Beast-Warrior', 'DARK', 8, 1000, 2800, '「剑斗兽 奥古斯都」＋「剑斗兽」怪兽×2 让自己场上的上记卡回到卡组的场合才能从额外卡组特殊召唤（不需要「融合」）。 ①：这张卡用上记的方法特殊召唤成功的场合才能发动。从额外卡组把1只7星以下的「剑斗兽」融合怪兽无视召唤条件特殊召唤。 ②：这张卡进行战斗的战斗阶段结束时让这张卡回到持有者的额外卡组才能发动。从卡组把2只「剑斗兽」怪兽特殊召唤。'),
(90582719, 'Gladiator Beast Andal', '剑斗兽 孤眼', '剣闘獣アンダル', 'Normal Monster', 'Beast-Warrior', 'EARTH', 4, 1900, 1500, '以高攻击力追逼敌人的独眼战熊。恐怖的速度与重量引以为傲的得意拳受了后不倒者是不存在的。'),
(52502677, 'Gladiator Beast Attorix', '剑斗兽 女斗', '剣闘獣アトリクス', 'Effect Monster', 'Beast-Warrior', 'EARTH', 4, 800, 2000, '①：这张卡用「剑斗兽」怪兽的效果特殊召唤成功的场合，从卡组·额外卡组把「剑斗兽 女斗」以外的1只「剑斗兽」怪兽送去墓地才能发动。直到结束阶段，这张卡变成和送去墓地的怪兽相同等级，当作同名卡使用。 ②：这张卡进行战斗的战斗阶段结束时让这张卡回到持有者卡组才能发动。从卡组把「剑斗兽 女斗」以外的1只「剑斗兽」怪兽特殊召唤。'),
(7573135, 'Gladiator Beast Augustus', '剑斗兽 奥古斯都尔', '剣闘獣アウグストル', 'Effect Monster', 'Winged Beast', 'DARK', 8, 2600, 1000, '①：这张卡用「剑斗兽」怪兽的效果特殊召唤成功时才能发动。从手卡把1只「剑斗兽」怪兽守备表示特殊召唤。这个效果特殊召唤的怪兽在结束阶段回到持有者卡组。 ②：这张卡进行战斗的战斗阶段结束时让这张卡回到持有者卡组才能发动。从卡组把「剑斗兽 奥古斯都」以外的1只「剑斗兽」怪兽特殊召唤。'),
(41470137, 'Gladiator Beast Bestiari', '剑斗兽 锐枪', '剣闘獣ベストロウリィ', 'Effect Monster', 'Winged Beast', 'WIND', 4, 1500, 800, '①：这张卡用「剑斗兽」怪兽的效果特殊召唤成功的场合，以场上1张魔法·陷阱卡为对象发动。那张卡破坏。 ②：这张卡进行战斗的战斗阶段结束时让这张卡回到持有者卡组才能发动。从卡组把「剑斗兽 枪斗」以外的1只「剑斗兽」怪兽特殊召唤。'),
(16990348, 'Gladiator Beast Charge', '猛进的剑斗兽', '猛進する剣闘獣', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以最多有自己场上的「剑斗兽」怪兽种类数量的场上的表侧表示的卡为对象才能发动。那些卡破坏。'),
(48958757, 'Gladiator Beast Claudius', '剑斗兽 克劳狄乌斯', '剣闘獣クラウディウス', 'Fusion Monster', 'Beast', 'DARK', 12, 3700, 2600, '「剑斗兽」怪兽×5 让自己的场上·墓地的上记的卡回到卡组·额外卡组的场合才能从额外卡组特殊召唤。 ①：这张卡用上记的方法特殊召唤的场合才能发动。下次的自己战斗阶段可以进行2次。 ②：1回合1次，对方把怪兽的效果发动的场合，可以把发动回合的以下效果发动。 ●自己回合：从卡组把1只「剑斗兽」怪兽特殊召唤。 ●对方回合：从额外卡组把1只11星以下的「剑斗兽」怪兽无视召唤条件特殊召唤。'),
(72246674, 'Gladiator Beast Dareios', '剑斗兽 大流士', '剣闘獣ダレイオス', 'Link Monster', 'Beast-Warrior', 'DARK', NULL, 1700, NULL, '包含「剑斗兽」怪兽的怪兽2只 这个卡名的①的效果1回合只能使用1次。 ①：这张卡连接召唤的场合才能发动。从自己的手卡·墓地把1只4星以下的「剑斗兽」怪兽特殊召唤。对方场上有怪兽存在的场合，也能作为代替从卡组把1只「剑斗兽」怪兽特殊召唤。这个回合，自己不是「剑斗兽」怪兽不能作为连接素材。 ②：自己场上的「剑斗兽」怪兽在对方战斗阶段中不会被战斗·效果破坏。'),
(25924653, 'Gladiator Beast Darius', '剑斗兽 战马', '剣闘獣ダリウス', 'Effect Monster', 'Beast-Warrior', 'EARTH', 4, 1700, 300, '①：这张卡用「剑斗兽」怪兽的效果特殊召唤成功时，以自己墓地1只「剑斗兽」怪兽为对象才能发动。那只怪兽效果无效特殊召唤。这张卡从场上离开时那只怪兽回到持有者卡组。 ②：这张卡进行战斗的战斗阶段结束时让这张卡回到持有者卡组才能发动。从卡组把「剑斗兽 马斗」以外的1只「剑斗兽」怪兽特殊召唤。'),
(31247589, 'Gladiator Beast Dimacari', '剑斗兽 双斗', '剣闘獣ディカエリィ', 'Effect Monster', 'Beast', 'EARTH', 4, 1600, 1200, '这张卡用名字带有「剑斗兽」的怪兽的效果特殊召唤成功的场合，这张卡在同1次的战斗阶段中可以作2次攻击。这张卡进行战斗的战斗阶段结束时可以让这张卡回到卡组，从卡组把「剑斗兽 双斗」以外的1只名字带有「剑斗兽」的怪兽在自己场上特殊召唤。'),
(33652635, 'Gladiator Beast Domitianus', '剑斗兽 多米提安诺斯', '剣闘獣ドミティアノス', 'Fusion Monster', 'Sea Serpent', 'DARK', 10, 3500, 1200, '「剑斗兽 维斯帕西亚努斯」＋「剑斗兽」怪兽×2 让自己场上的上记卡回到卡组的场合才能从额外卡组特殊召唤（不需要「融合」）。 ①：1回合1次，对方把怪兽的效果发动时才能发动。那个发动无效并破坏。 ②：只要这张卡在怪兽区域存在，对方怪兽的攻击对象由自己选择。 ③：这张卡进行战斗的战斗阶段结束时让这张卡回到持有者的额外卡组才能发动。从卡组把1只「剑斗兽」怪兽特殊召唤。'),
(62000467, 'Gladiator Beast Dragases', '剑斗兽 德拉加瑟斯', '剣闘獣ドラガシス', 'Link Monster', 'Winged Beast', 'WIND', NULL, 2000, NULL, '「剑斗兽」怪兽2只 这个卡名的②的效果1回合只能使用1次。 ①：自己的「剑斗兽」怪兽攻击的场合，那只怪兽不会被那次战斗破坏，对方直到伤害步骤结束时魔法·陷阱·怪兽的效果不能发动。 ②：这张卡进行战斗的战斗阶段结束时让这张卡回到持有者的额外卡组才能发动。从卡组把2只「剑斗兽」怪兽特殊召唤（同名卡最多1张）。'),
(57731460, 'Gladiator Beast Equeste', '剑斗兽 飞骑', '剣闘獣エクイテ', 'Effect Monster', 'Winged Beast', 'WIND', 4, 1600, 1200, '这张卡用名字带有「剑斗兽」的怪兽的效果特殊召唤成功时，从自己墓地选择1张名字带有「剑斗兽」的卡加入手卡。这张卡进行战斗的战斗阶段结束时可以让这张卡回到卡组，从卡组把「剑斗兽 骑斗」以外的1只名字带有「剑斗兽」的怪兽在自己场上特殊召唤。'),
(73285669, 'Gladiator Beast Essedarii', '剑斗兽 战驾', '剣闘獣エセダリ', 'Fusion Monster', 'Beast', 'EARTH', 5, 2500, 1400, '名字带有「剑斗兽」的怪兽×2 让自己场上的上记的卡回到卡组的场合才能从额外卡组特殊召唤（不需要「融合」）。'),
(90957527, 'Gladiator Beast Gaiodiaz', '剑斗兽 乔治', '剣闘獣ゲオルディアス', 'Fusion Monster', 'Dinosaur', 'DARK', 7, 2600, 1500, '「剑斗兽 斯巴达克斯」＋名字带有「剑斗兽」的怪兽 把自己场上存在的上记的卡回到卡组的场合才能从融合卡组特殊召唤（不需要「融合」魔法卡）。这张卡战斗破坏怪兽送去墓地时，给与对方基本分破坏怪兽的守备力数值的伤害。这张卡进行战斗的战斗阶段结束时可以让这张卡回到融合卡组，从卡组把「剑斗兽 斯巴达克斯」以外的2只名字带有「剑斗兽」的怪兽在自己场上特殊召唤。'),
(26582143, 'Gladiator Beast Gistel', '剑斗兽 教鞭', '剣闘獣ギステル', 'Effect Monster', 'Beast', 'EARTH', 3, 1200, 2000, '这个卡名的①②的效果1回合各能使用1次。 ①：把手卡的这张卡和手卡1只「剑斗兽」怪兽给对方观看才能发动。那2只特殊召唤。 ②：这张卡用「剑斗兽」怪兽的效果特殊召唤的场合才能发动。从卡组把1张「剑斗」魔法·陷阱卡加入手卡。 ③：这张卡进行战斗的战斗阶段结束时，让这张卡回到卡组才能发动。从卡组把「剑斗兽 师斗」以外的1只「剑斗兽」怪兽特殊召唤。'),
(48156348, 'Gladiator Beast Gyzarus', '剑斗兽 凯撒列斯', '剣闘獣ガイザレス', 'Fusion Monster', 'Winged Beast', 'DARK', 6, 2400, 1500, '「剑斗兽 枪斗」＋「剑斗兽」怪兽 让自己场上的上记卡回到卡组的场合才能从额外卡组特殊召唤（不需要「融合」）。 ①：这张卡特殊召唤成功时，以场上最多2张卡为对象才能发动。那些卡破坏。 ②：这张卡进行战斗的战斗阶段结束时让这张卡回到持有者的额外卡组才能发动。从卡组把「剑斗兽 枪斗」以外的2只「剑斗兽」怪兽特殊召唤。'),
(27346636, 'Gladiator Beast Heraklinos', '剑斗兽 赫拉克雷诺斯', '剣闘獣ヘラクレイノス', 'Fusion Monster', 'Beast-Warrior', 'FIRE', 8, 3000, 2800, '「剑斗兽 绳斗」＋名字带有「剑斗兽」的怪兽×2 让自己场上的上记的卡回到卡组的场合才能从额外卡组特殊召唤（不需要「融合」魔法卡）。只要这张卡在场上表侧表示存在，可以通过丢弃1张手卡，魔法·陷阱卡的发动无效并破坏。'),
(4253484, 'Gladiator Beast Hoplomus', '剑斗兽 重斗', '剣闘獣ホプロムス', 'Effect Monster', 'Rock', 'EARTH', 4, 700, 2100, '这张卡用名字带有「剑斗兽」的怪兽的效果特殊召唤成功的场合，这张卡的原本守备力变成2400。这张卡进行战斗的战斗阶段结束时可以让这张卡回到卡组，从卡组把「剑斗兽 重斗」以外的1只名字带有「剑斗兽」的怪兽在自己场上特殊召唤。'),
(2067935, 'Gladiator Beast Lanista', '剑斗兽 教斗', '剣闘獣ラニスタ', 'Effect Monster', 'Winged Beast', 'WIND', 4, 1800, 1200, '这张卡用名字带有「剑斗兽」的怪兽的效果特殊召唤成功时，选择自己墓地存在的1只名字带有「剑斗兽」的怪兽才能发动。选择的怪兽从游戏中除外，直到结束阶段时当作和那只怪兽同名卡使用。这张卡进行战斗的战斗阶段结束时可以让这张卡回到卡组，从卡组把「剑斗兽 教斗」以外的1只名字带有「剑斗兽」的怪兽在自己场上特殊召唤。'),
(78868776, 'Gladiator Beast Laquari', '剑斗兽 炎索', '剣闘獣ラクエル', 'Effect Monster', 'Beast-Warrior', 'FIRE', 4, 1800, 400, '这张卡用名字带有「剑斗兽」的怪兽的效果特殊召唤成功的场合，这张卡的原本攻击力变成2100。这张卡进行战斗的战斗阶段结束时可以让这张卡回到卡组，从卡组把「剑斗兽 绳斗」以外的1只名字带有「剑斗兽」的怪兽在自己场上特殊召唤。'),
(5975022, 'Gladiator Beast Murmillo', '剑斗兽 鱼兜', '剣闘獣ムルミロ', 'Effect Monster', 'Fish', 'WATER', 3, 800, 400, '这张卡用名字带有「剑斗兽」的怪兽的效果特殊召唤成功时，把场上1只表侧表示怪兽破坏。这张卡进行战斗的战斗阶段结束时可以让这张卡回到卡组，从卡组把「剑斗兽 鱼斗」以外的1只名字带有「剑斗兽」的怪兽在自己场上特殊召唤。'),
(29357956, 'Gladiator Beast Nerokius', '剑斗兽 尼禄基乌斯', '剣闘獣ネロキウス', 'Fusion Monster', 'Winged Beast', 'DARK', 8, 2800, 1900, '「剑斗兽」怪兽×3 让自己场上的上记卡回到卡组的场合才能从额外卡组特殊召唤（不需要「融合」）。 ①：这张卡不会被战斗破坏，这张卡进行战斗的场合，对方直到伤害步骤结束时魔法·陷阱·怪兽的效果不能发动。 ②：这张卡进行战斗的战斗阶段结束时让这张卡回到额外卡组才能发动。从卡组把2只「剑斗兽」怪兽特殊召唤。'),
(67385964, 'Gladiator Beast Noxious', '剑斗兽 罪徒', '剣闘獣ノクシウス', 'Effect Monster', 'Beast-Warrior', 'DARK', 5, NULL, 1000, '①：对方怪兽的直接攻击宣言时才能发动。这张卡从手卡特殊召唤，那只对方怪兽的攻击对象转移为这张卡进行伤害计算。这张卡不会被那次战斗破坏。 ②：这张卡用「剑斗兽」怪兽的效果特殊召唤成功的场合才能发动。从卡组把1只「剑斗兽」怪兽送去墓地。 ③：这张卡进行战斗的战斗阶段结束时让这张卡回到持有者卡组才能发动。从卡组把「剑斗兽 罪斗」以外的1只「剑斗兽」怪兽特殊召唤。'),
(29590752, 'Gladiator Beast Octavius', '剑斗兽 屋大维', '剣闘獣オクタビウス', 'Effect Monster', 'Winged Beast', 'LIGHT', 7, 2500, 1200, '这张卡用名字带有「剑斗兽」的怪兽的效果特殊召唤成功时，把魔法与陷阱卡区域盖放的1张卡破坏。这张卡进行战斗的自己的战斗阶段结束时，丢弃1张手卡或这张卡回到卡组。'),
(612115, 'Gladiator Beast Retiari', '剑斗兽 网戟', '剣闘獣レティアリィ', 'Effect Monster', 'Aqua', 'WATER', 3, 1200, 800, '这张卡用名字带有「剑斗兽」的怪兽的效果特殊召唤成功时，可以选择对方墓地1张卡除外。这张卡进行战斗的战斗阶段结束时可以通过让这张卡回到卡组，从卡组把「剑斗兽 网斗」以外的1只名字带有「剑斗兽」的怪兽特殊召唤。'),
(16003979, 'Gladiator Beast Sagittarii', '剑斗兽 弓骑', '剣闘獣サジタリィ', 'Effect Monster', 'Winged Beast', 'WIND', 3, 1400, 1000, '①：这张卡用「剑斗兽」怪兽的效果特殊召唤成功的场合，从手卡丢弃1张「剑斗兽」卡才能发动。自己从卡组抽2张。 ②：这张卡进行战斗的战斗阶段结束时让这张卡回到持有者卡组才能发动。从卡组把「剑斗兽 射斗」以外的1只「剑斗兽」怪兽特殊召唤。'),
(2619149, 'Gladiator Beast Samnite', '剑斗兽 盾斗', '剣闘獣サムニテ', 'Effect Monster', 'Beast', 'EARTH', 3, 1600, 1200, '这张卡用名字带有「剑斗兽」的怪兽的效果特殊召唤成功的场合，这张卡战斗破坏对方怪兽送去墓地时，可以从自己卡组把1张名字带有「剑斗兽」的卡加入手卡。这张卡进行战斗的战斗阶段结束时可以让这张卡回到卡组，从卡组把「剑斗兽 盾斗」以外的1只名字带有「剑斗兽」的怪兽在自己场上特殊召唤。'),
(77642288, 'Gladiator Beast Secutor', '剑斗兽 追鬣', '剣闘獣セクトル', 'Effect Monster', 'Reptile', 'WIND', 4, 400, 300, '这张卡用名字带有「剑斗兽」的怪兽的效果特殊召唤成功的场合，这张卡进行战斗的战斗阶段结束时，从卡组把「剑斗兽 追斗」以外的2只名字带有「剑斗兽」的怪兽在自己场上特殊召唤。'),
(79580323, 'Gladiator Beast Spartacus', '剑斗兽 斯巴达克斯', '剣闘獣スパルティクス', 'Effect Monster', 'Dinosaur', 'EARTH', 5, 2200, 1600, '「剑斗兽 重斗」以外的效果不能把这张卡特殊召唤。这张卡特殊召唤成功时，从卡组把1张名字带有「斗器」的装备魔法卡加入手卡。这张卡进行战斗的战斗阶段结束时可以让这张卡回到卡组，从卡组把「剑斗兽 斯巴达克斯」以外的1只名字带有「剑斗兽」的怪兽在自己场上特殊召唤。'),
(30864377, 'Gladiator Beast Tamer Editor', '剑斗兽总监 主斗', '剣闘獣総監エーディトル', 'Fusion Monster', 'Beast-Warrior', 'DARK', 8, 2400, 3000, '5星以上的「剑斗兽」怪兽×2 让自己场上的上记卡回到卡组的场合才能从额外卡组特殊召唤（不需要「融合」）。这张卡不能作为融合素材。 ①：1回合1次，可以发动。从额外卡组把「剑斗兽总监 主斗」以外的1只「剑斗兽」融合怪兽无视召唤条件特殊召唤。 ②：自己的「剑斗兽」怪兽进行战斗的战斗阶段结束时让那1只怪兽回到持有者的卡组·额外卡组才能发动。从卡组把1只「剑斗兽」怪兽特殊召唤。'),
(65984457, 'Gladiator Beast Torax', '剑斗兽 轻斗', '剣闘獣トラケス', 'Effect Monster', 'Fish', 'WATER', 3, 1400, 400, '这张卡用名字带有「剑斗兽」的怪兽的效果特殊召唤成功的场合，这张卡进行战斗的战斗阶段结束时可以让这张卡回到卡组并抽1张卡。'),
(50893987, 'Gladiator Beast Tygerius', '剑斗兽 老虎', '剣闘獣ティゲル', 'Effect Monster', 'Beast', 'EARTH', 4, 1800, 800, '这张卡不能作为融合素材怪兽使用。这张卡用名字带有「剑斗兽」的怪兽的效果特殊召唤成功时，可以从手卡把1张名字带有「剑斗兽」的卡丢弃，从自己卡组把1只名字带有「剑斗兽」的怪兽加入手卡。'),
(66290900, 'Gladiator Beast United', '团结的剑斗兽', '団結する剣闘獣', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张，这张卡发动的回合，自己不用「剑斗兽」怪兽不能攻击宣言。 ①：自己·对方的战斗阶段才能发动。从自己的手卡·场上·墓地让「剑斗兽」融合怪兽卡决定的融合素材怪兽回到持有者卡组，把那1只融合怪兽从额外卡组无视召唤条件特殊召唤。'),
(88996322, 'Gladiator Beast Vespasius', '剑斗兽 韦斯帕西亚斯', '剣闘獣ウェスパシアス', 'Effect Monster', 'Sea Serpent', 'WATER', 7, 2300, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：自己的「剑斗兽」怪兽和怪兽进行战斗的伤害步骤开始时才能发动。这张卡从手卡特殊召唤。 ②：只要「剑斗兽」怪兽的效果特殊召唤的这张卡在怪兽区域存在，自己场上的怪兽的攻击力上升500。 ③：这张卡进行战斗的战斗阶段结束时让这张卡回到持有者卡组才能发动。从卡组把「剑斗兽 维斯帕西亚努斯」以外的1只「剑斗兽」怪兽特殊召唤。'),
(96216229, 'Gladiator Beast War Chariot', '剑斗兽的战车', '剣闘獣の戦車', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '①：自己场上有「剑斗兽」怪兽存在，怪兽的效果发动时才能发动。那个发动无效并破坏。'),
(8730435, 'Gladiator Beast''s Battle Archfiend Shield', '剑斗兽的斗器 恶魔之盾', '剣闘獣の闘器デーモンズシールド', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '名字带有「剑斗兽」的怪兽才能装备。装备怪兽被破坏的场合，作为代替把这张卡破坏。装备怪兽从自己场上回到卡组让这张卡被送去墓地时，这张卡回到手卡。'),
(25407406, 'Gladiator Beast''s Battle Gladius', '剑斗兽的斗器 短剑', '剣闘獣の闘器グラディウス', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '名字带有「剑斗兽」的怪兽才能装备。装备怪兽的攻击力上升300。装备怪兽从自己场上回到卡组让这张卡被送去墓地时，这张卡回到手卡。'),
(99013397, 'Gladiator Beast''s Battle Halberd', '剑斗兽的斗器 长戟', '剣闘獣の闘器ハルバード', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '名字带有「剑斗兽」的怪兽才能装备。装备怪兽进行攻击的伤害步骤结束时，把场上1张魔法或者陷阱卡破坏。装备怪兽从自己场上回到卡组让这张卡被送去墓地时，这张卡回到手卡。'),
(52496105, 'Gladiator Beast''s Battle Manica', '剑斗兽的斗器 护臂', '剣闘獣の闘器マニカ', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '名字带有「剑斗兽」的怪兽才能装备。只要有这张卡装备，装备怪兽不会被战斗破坏（伤害计算适用）。装备怪兽从自己场上回到卡组让这张卡被送去墓地时，这张卡回到手卡。'),
(20201255, 'Gladiator Beast''s Comeback', '再起的剑斗兽', '再起する剣闘獣', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：从自己的手卡·墓地选相同种族的怪兽不在自己场上存在的1只「剑斗兽」怪兽特殊召唤。这个效果特殊召唤的怪兽不会被战斗破坏。'),
(98891840, 'Gladiator Beast''s Respite', '休息的剑斗兽', '休息する剣闘獣', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '从自己手卡把2张名字带有「剑斗兽」的卡回到卡组。那之后，从自己卡组抽3张卡。'),
(97234686, 'Gladiator Lash', '剑斗变化', 'グラディアル・チェンジ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上有名字带有「剑斗兽」的怪兽特殊召唤时才能发动。对方选择1张手卡丢弃。'),
(52394047, 'Gladiator Naumachia', '剑斗海战', '剣闘海戦', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：只要这张卡在魔法与陷阱区域存在并在自己场上有「剑斗兽」怪兽存在，可以攻击的对方怪兽必须作出攻击。 ②：1回合1次，从自己的手卡·墓地让1只「剑斗兽」怪兽回到卡组，以自己场上1只「剑斗兽」怪兽为对象才能发动。那只怪兽的攻击力直到回合结束时上升原本守备力数值。 ③：魔法与陷阱区域的这张卡被效果破坏的场合才能发动。这个回合，自己的「剑斗兽」怪兽不会被战斗破坏。'),
(35224440, 'Gladiator Proving Ground', '剑斗训练所', '剣闘訓練所', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '从自己卡组把1只4星以下的名字带有「剑斗兽」的怪兽加入手卡。'),
(93684009, 'Gladiator Rejection', '剑斗排斥波', '剣闘排斥波', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：自己场上的「剑斗兽」怪兽在战斗阶段以外不会成为对方的效果的对象。 ②：从自己卡组有「剑斗兽」怪兽特殊召唤的场合才能发动。相同种族的怪兽不在自己场上存在的1只「剑斗兽」怪兽从卡组守备表示特殊召唤。'),
(9780364, 'Gladiator Taming', '剑斗调教', '剣闘調教', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '场上有名字带有「剑斗兽」的怪兽存在的场合，可以从以下效果选择1个发动。 ●选择对方场上表侧表示存在的1只怪兽，把表示形式变更。 ●选择对方场上1只名字带有「剑斗兽」的怪兽直到结束阶段时得到控制权。'),
(24285858, 'Gladiator''s Return', '剑斗归还', 'グラディアル・リターン', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '墓地存在的3张名字带有「剑斗兽」的卡回到卡组。那之后，从自己卡组抽1张卡。'),
(9677699, 'Glass Slippers', '水晶鞋', 'ガラスの靴', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：装备怪兽的种族是天使族的场合，装备怪兽的攻击力上升1000。天使族以外的场合，装备怪兽不能攻击，攻击力下降1000。 ②：装备怪兽被破坏让这张卡被送去墓地的场合，以自己场上1只「灰姑娘」为对象才能发动。那只自己的「灰姑娘」把这张卡装备。'),
(14464864, 'Gleipnir, the Fetters of Fenrir', '神之桎梏 格莱普尼尔', '神の桎梏グレイプニル', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '从自己卡组把1只名字带有「极星」的怪兽加入手卡。'),
(899287, 'Glife the Phantom Bird', '怪鸟格莱弗', '怪鳥グライフ', 'Effect Monster', 'Winged Beast', 'WIND', 4, 1500, 1500, '这个卡名的②的效果1回合只能使用1次。 ①：把这张卡从手卡丢弃才能发动。从卡组把1张「急流山的金宫」加入手卡。 ②：这张卡召唤·特殊召唤成功的场合，以对方的魔法与陷阱区域1张卡为对象才能发动。那张卡破坏。'),
(61962135, 'Glorious Illusion', '闪光之幻想', '閃光のイリュージョン', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '从自己墓地选择1只名字带有有「光道」的怪兽，攻击表示特殊召唤。每次自己的结束阶段，从卡组上面把2张卡送去墓地。这张卡从场上离开时，那只怪兽破坏。那只怪兽从场上离开时这张卡破坏。'),
(60944809, 'Glorious Numbers', '荣光号数', 'グローリアス・ナンバーズ', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上没有怪兽存在的场合，以自己墓地1只「No.」超量怪兽为对象才能发动。那只怪兽特殊召唤。那之后，自己从卡组抽1张。 ②：把墓地的这张卡除外，以自己场上1只「No.」超量怪兽为对象才能发动。把1张手卡在那只怪兽下面重叠作为超量素材。'),
(75719089, 'Glory of the Noble Knights', '光荣的圣骑士团', '栄光の聖騎士団', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己场上1只「圣骑士」怪兽为对象才能发动。从卡组选1张那只自己怪兽可以装备的装备魔法卡给那只怪兽装备。'),
(92964816, 'Glow-Up Bloom', '成长花', 'グローアップ・ブルーム', 'Tuner Monster', 'Zombie', 'DARK', 1, NULL, NULL, '这个卡名的效果1回合只能使用1次。 ①：这张卡被送去墓地的场合，把墓地的这张卡除外才能发动。从卡组把1只5星以上的不死族怪兽加入手卡。场地区域有「不死世界」存在的场合，也能不加入手卡特殊召唤。这个效果的发动后，直到回合结束时自己不是不死族怪兽不能特殊召唤。'),
(67441435, 'Glow-Up Bulb', '成长球茎', 'グローアップ・バルブ', 'Tuner Monster', 'Plant', 'EARTH', 1, 100, 100, '这个卡名的效果在决斗中只能使用1次。 ①：这张卡在墓地存在的场合才能发动。自己卡组最上面的卡送去墓地，这张卡特殊召唤。'),
(53860621, 'Glowing Crossbow', '炫发弩', 'グローウィング・ボウガン', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '「黑羽」怪兽才能装备。这个卡名的②③的效果1回合各能使用1次。 ①：装备怪兽的攻击力·守备力上升500。 ②：装备怪兽战斗破坏对方怪兽的场合才能发动。对方手卡随机选1张丢弃。 ③：装备怪兽成为同调素材让这张卡被送去墓地的场合才能发动。墓地的这张卡加入手卡。'),
(8576764, 'Gluttonous Reptolphin Greethys', '贪食鱼 格里迪斯', '貪食魚グリーディス', 'Tuner Monster', 'Fish', 'WATER', 3, 1000, 1000, '这个卡名的①的效果1回合只能使用1次。 ①：以持有对方手卡数量以下的等级的自己墓地1只鱼族·海龙族·水族怪兽为对象才能发动。那只怪兽特殊召唤。这个效果特殊召唤的怪兽在这个回合不能把效果发动。 ②：这张卡作为同调素材送去墓地的场合才能发动。这张卡为同调素材的同调怪兽的攻击力·守备力上升对方手卡数量×200。'),
(101303094, 'GMX - ALLOS', NULL, NULL, 'Fusion Monster', 'Dinosaur', 'LIGHT', 8, 3000, 900, NULL),
(101303095, 'GMX - VELOX', NULL, NULL, 'Fusion Monster', 'Dinosaur', 'DARK', 8, 2700, 1300, NULL),
(101303096, 'GMX Applied Experiment #55', NULL, NULL, 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, NULL),
(101303092, 'GMX Associate Noma', NULL, NULL, 'Effect Monster', 'Reptile', 'DARK', 4, 900, 1300, NULL),
(101303091, 'GMX Chairman Kimridge', NULL, NULL, 'Effect Monster', 'Psychic', 'LIGHT', 4, 1000, 900, NULL),
(101303090, 'GMX Researcher Selande', NULL, NULL, 'Effect Monster', 'Warrior', 'FIRE', 3, 1500, 700, NULL),
(58655504, 'Gnomaterial', '禁采令地精灵', 'ノーマテリア', 'Effect Monster', 'Fairy', 'EARTH', 1, NULL, 1000, '这个卡名的效果1回合只能使用1次。 ①：自己场上没有卡存在，对方对怪兽的特殊召唤成功的场合，把这张卡从手卡丢弃，以对方场上1只表侧表示怪兽为对象才能发动。这个回合，那只怪兽不能解放，也不能作为融合·同调·超量·连接召唤的素材。'),
(40227329, 'Go! - D/D/D Divine Zero King Rage', 'GO－DDD 神零王 零神零怒', 'GO－DDD神零王ゼロゴッド・レイジ', 'Pendulum Effect Monster', 'Fiend', 'DARK', 10, NULL, NULL, '①：把这张卡以外的自己场上1只怪兽解放才能发动。从以下效果选1个直到回合结束时适用。 ●这张卡可以直接攻击。 ●对方不能把魔法与陷阱区域的卡的效果发动。 ●对方不能把手卡·墓地的卡的效果发动。 ②：对方基本分是4000以下的场合，这张卡的攻击宣言时才能发动。这张卡的攻击力直到回合结束时上升对方基本分数值。 ③：这张卡不会被战斗破坏，这张卡的战斗发生的对自己的战斗伤害变成0。'),
(78658564, 'Goblin Attack Force', '格布林突击部队', 'ゴブリン突撃部隊', 'Effect Monster', 'Warrior', 'EARTH', 4, 2300, NULL, '①：这张卡攻击的场合，战斗阶段结束时变成守备表示，直到下次的自己回合的结束时不能把表示形式变更。'),
(34001672, 'Goblin Biker Big Gabonga', '格布林百罗刹 巨魁加蓬迦', '百鬼羅刹 巨魁ガボンガ', 'XYZ Monster', 'Beast-Warrior', 'LIGHT', 3, 2100, NULL, '3星怪兽×2 这个卡名的①②③的效果1回合各能使用1次。 ①：这张卡超量召唤的场合才能发动。从卡组把1只「哥布林」怪兽加入手卡。 ②：场上的超量素材被取除的场合，以场上1只其他的表侧表示怪兽为对象才能发动。那只怪兽作为这张卡的超量素材。 ③：自己·对方的结束阶段才能发动。从卡组把1只「哥布林」怪兽作为这张卡的超量素材。'),
(27868563, 'Goblin Biker Boom Mach', '格布林百罗刹 神速布恩', '百鬼羅刹 神速ブーン', 'Effect Monster', 'Warrior', 'WIND', 3, 1300, NULL, '①：这张卡在手卡·墓地存在的场合，自己·对方的主要阶段才能发动。场上1个超量素材取除，这张卡特殊召唤。这个效果的发动后，直到下个回合的结束时自己不能把「百鬼罗刹 神速布恩」特殊召唤。'),
(51473858, 'Goblin Biker Clatter Sploder', '格布林百罗刹 爆音克拉塔', '百鬼羅刹 爆音クラッタ', 'Effect Monster', 'Beast-Warrior', 'FIRE', 3, 1500, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合，以「百鬼罗刹 爆音克拉特」以外的自己墓地1只「哥布林」怪兽为对象才能发动。那只怪兽特殊召唤。 ②：这张卡在墓地存在的场合，对方主要阶段才能发动。场上1个超量素材取除，这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。'),
(24079759, 'Goblin Biker Dugg Charger', '格布林百罗刹 特攻达格', '百鬼羅刹 特攻ダグ', 'Effect Monster', 'Warrior', 'EARTH', 3, 1600, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在手卡存在的场合才能发动。场上1个超量素材取除，这张卡特殊召唤。 ②：这张卡召唤·特殊召唤的场合才能发动。从卡组把1张「哥布林骑手」魔法·陷阱卡加入手卡。'),
(64327901, 'Goblin Biker Grand Bash', '格布林百罗刹大集会', '百鬼羅刹大集会', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的③的效果1回合只能使用1次。 ①：自己场上的「哥布林」怪兽的攻击力上升自己场上的「哥布林」怪兽数量×300。 ②：自己在通常召唤外加上只有1次，自己主要阶段可以把1只「哥布林」怪兽召唤。 ③：可以以自己场上2只「哥布林」怪兽为对象，从以下效果选择1个发动。 ●那之内1只的等级变成和另1只的等级相同。 ●那2只的等级变成各自的原本等级合计的等级。'),
(29111045, 'Goblin Biker Grand Breakout', '格布林百罗刹大收监', '百鬼羅刹大収監', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：把自己场上1只怪兽解放才能发动。从卡组把1只「哥布林」怪兽特殊召唤。这个效果特殊召唤的怪兽在这个回合不能攻击。 ②：自己或对方的怪兽的攻击宣言时，把墓地的这张卡除外，把自己场上的「哥布林」超量怪兽的超量素材任意数量取除才能发动。对方场上的全部怪兽的攻击力直到回合结束时下降取除数量×1000。'),
(15094540, 'Goblin Biker Grand Crisis', '格布林百罗刹大危机', '百鬼羅刹大危機', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：以自己场上1只「哥布林」怪兽和对方场上1只怪兽或者自己墓地1只「哥布林」怪兽和对方墓地1只怪兽为对象才能发动。那2只怪兽除外。 ②：把魔法与陷阱区域的表侧表示的这张卡送去墓地，以自己的除外状态的5只「哥布林」怪兽为对象才能发动（同名卡最多1张）。那些怪兽特殊召唤。'),
(90711610, 'Goblin Biker Grand Entrance', '格布林百罗刹大参上', '百鬼羅刹大参上', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：从卡组把1只「哥布林」怪兽加入手卡。那之后，以下效果可以适用。 ●场上1个超量素材取除，从手卡把1只4星以下的「哥布林」怪兽特殊召唤。 ②：把墓地的这张卡除外才能发动。场上1个超量素材取除。那之后，可以从自己墓地把1只「哥布林」怪兽加入手卡。'),
(90946420, 'Goblin Biker Grand Pileup', '格布林百罗刹大重叠', '百鬼羅刹大重畳', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：以自己场上1只超量怪兽为对象才能发动。把1只「哥布林」超量怪兽在作为对象的自己的超量怪兽上面重叠当作超量召唤从额外卡组特殊召唤，把这张卡作为那超量素材。 ②：把墓地的这张卡除外，以自己场上1只「哥布林」超量怪兽和自己或对方的墓地1张卡为对象才能发动。把成为对象的墓地的卡作为成为对象的场上的怪兽的超量素材。'),
(50311058, 'Goblin Biker Grand Stampede', '格布林百罗刹大暴走', '百鬼羅刹大暴走', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：自己·对方的主要阶段才能发动。只用自己场上的「哥布林」怪兽为素材进行超量召唤。 ②：自己场上有「哥布林」超量怪兽存在的场合，以场上1只效果怪兽为对象才能发动。场上1个超量素材取除，作为对象的怪兽的效果直到回合结束时无效。'),
(64257161, 'Goblin Biker Mean Merciless', '格布林百罗刹 冷血米安达', '百鬼羅刹 冷血ミアンダ', 'Effect Monster', 'Fiend', 'WATER', 3, 1300, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。从手卡把「百鬼罗刹 冷血米安德」以外的1只「哥布林」怪兽特殊召唤。 ②：这张卡在墓地存在的场合，自己主要阶段才能发动。场上1个超量素材取除，这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。'),
(44241999, 'Goblin Biker Troika Griare', '格布林百罗刹 格里阿雷三杰', '百鬼羅刹 グリアーレ三傑', 'XYZ Monster', 'Warrior', 'LIGHT', 3, 1700, NULL, '3星怪兽×2只以上 ①：场上的超量素材是3个以上的场合，自己的「哥布林」怪兽可以直接攻击。 ②：1回合1次，这张卡在怪兽区域存在的状态，怪兽召唤·特殊召唤的场合，以那之内的1只为对象才能发动。场上1个超量素材取除，作为对象的怪兽的表示形式变更。 ③：1回合1次，对方怪兽的攻击宣言时才能发动。场上1个超量素材取除，那次攻击无效。'),
(46014517, 'Goblin Bikers Gone Bonkers', '格布林百罗刹唯我独尊', '百鬼羅刹唯我独尊', 'XYZ Monster', 'Fiend', 'DARK', 6, 2500, 2000, '6星怪兽×2只以上 这个卡名的①②的效果1回合各能使用1次。 ①：以最多有自己场上的「哥布林」怪兽数量的对方场上的表侧表示怪兽为对象才能发动。自己场上1个超量素材取除，把作为对象的怪兽作为这张卡的超量素材。 ②：对方回合，以最多有自己场上的「哥布林」超量怪兽数量的对方场上的卡为对象才能发动。自己场上3个超量素材取除，作为对象的卡送去墓地。'),
(55320758, 'Goblin Bikers Gone Wild', '天上天下格布林百罗刹', '天上天下百鬼羅刹', 'Effect Monster', 'Fiend', 'DARK', 6, 2400, NULL, '这个卡名的②③的效果1回合各能使用1次。 ①：自己场上的怪兽不存在的场合或者只有「哥布林」怪兽的场合，这张卡可以不用解放作召唤。 ②：这张卡召唤·特殊召唤的场合才能发动。从卡组把1只4星以下的「哥布林」怪兽特殊召唤。 ③：这张卡被送去墓地的场合，以场上1张卡为对象才能发动。那张卡作为自己场上1只「哥布林」超量怪兽的超量素材。'),
(66707058, 'Goblin Black Ops', '哥布林暗杀部队', 'ゴブリン暗殺部隊', 'Effect Monster', 'Beast-Warrior', 'DARK', 4, 1300, NULL, '这张卡可以直接攻击对方玩家。这张卡攻击的场合，战斗阶段结束时变成守备表示。直到下次的自己回合结束时这张卡不能把表示形式改变。'),
(12057781, 'Goblin Calligrapher', '落空格布林', 'スカゴブリン', 'Normal Monster', 'Fiend', 'DARK', 1, 400, 400, '为了完全弄懂暗黑界的文字，而日日精进的小矮人。将一切精力全部奉献于研究之中。'),
(18658572, 'Goblin Circus', '哥布林杂耍艺人', '見世物ゴブリン', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '每次自己的结束阶段，自己卡组最下面的卡给双方确认，那张卡在自己卡组最上面放置或里侧表示从游戏中除外。'),
(18960169, 'Goblin Decoy Squad', '哥布林佯动部队', 'ゴブリン陽動部隊', 'Effect Monster', 'Warrior', 'DARK', 4, 1000, NULL, '这张卡给与对方基本分战斗伤害时，可以从自己卡组抽1张卡。这张卡攻击的场合，战斗阶段结束时变成守备表示，直到下次的自己回合的结束阶段时不能把表示形式改变。'),
(85306040, 'Goblin Elite Attack Force', '哥布林精英部队', 'ゴブリンエリート部隊', 'Effect Monster', 'Fiend', 'EARTH', 4, 2200, 1500, '①：这张卡攻击的场合，战斗阶段结束时变成守备表示，直到下次的自己回合的结束时不能把表示形式变更。'),
(4149689, 'Goblin Fan', '天狗的羽扇', '天狗のうちわ', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：只要这张卡在魔法与陷阱区域存在，2星以下的怪兽在反转召唤成功时破坏。这个时候，那只怪兽不能把场上发动的效果发动。'),
(85123771, 'Goblin Freefall Squad', '格布林降下部队', 'ゴブリン降下部隊', 'Effect Monster', 'Warrior', 'WIND', 4, NULL, 2000, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡从手卡攻击表示特殊召唤的场合，以对方场上1只效果怪兽为对象才能发动。这张卡变成守备表示。作为对象的怪兽的效果在这张卡表侧守备表示存在期间无效化。 ②：这张卡在墓地存在的状态，对方场上有怪兽特殊召唤的场合，丢弃1张手卡才能发动。这张卡加入手卡。'),
(18590133, 'Goblin King', '哥布林王', 'キングゴブリン', 'Effect Monster', 'Fiend', 'DARK', 1, NULL, NULL, '若自己场上有除这张卡以外的恶魔族怪兽存在，则这张卡不能被攻击。这张卡的攻击力·守备力成为与全场除这张卡以外的恶魔族怪兽数量×1000点等同的数值。'),
(34251483, 'Goblin Marauding Squad', '哥布林冲锋部队', 'ゴブリン切り込み部隊', 'Effect Monster', 'Beast-Warrior', 'EARTH', 4, 1900, NULL, '这张卡的攻击宣言时，对方不能把魔法·陷阱·效果怪兽的效果发动。这张卡攻击的场合，战斗阶段结束时变成守备表示，直到下次的自己回合结束时这张卡不能把表示形式变更。'),
(425934, 'Goblin of Greed', '强欲格布林', '強欲ゴブリン', 'Effect Monster', 'Fiend', 'EARTH', 4, 1000, 1800, '只要这张卡在自己场上以表侧表示存在，双方都不能发动「通过丢弃手卡来发动」的效果。'),
(69632396, 'Goblin Out of the Frying Pan', '哥布林的敷衍了事', 'ゴブリンのその場しのぎ', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '支付500基本分。魔法卡的发动无效，那张卡回到持有者的手卡。'),
(12755462, 'Goblin Pothole Squad', '哥布林埋穴部队', 'ゴブリン穴埋め部隊', 'Effect Monster', 'Warrior', 'EARTH', 4, 1500, 400, '这张卡召唤成功时，陷阱卡不能发动。此外，只要这张卡在场上表侧表示存在，怪兽召唤·反转召唤·特殊召唤成功时，名字带有「落穴」的陷阱卡不能发动。'),
(82324312, 'Goblin Recon Squad', '哥布林侦察部队', 'ゴブリン偵察部隊', 'Effect Monster', 'Warrior', 'WIND', 4, 1700, NULL, '这张卡直接攻击对方玩家成功的场合，可以随机把对方1张手卡确认。确认的卡是魔法卡的场合，那张卡送去墓地。这张卡攻击的场合，战斗阶段结束时变成守备表示。直到下次的自己回合结束时这张卡不能把表示形式改变。'),
(45311864, 'Goblin Thief', '哥布林盗贼', '盗人ゴブリン', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：给与对方500伤害。自己回复500基本分。'),
(63665875, 'Goblin Zombie', '格布林僵尸', 'ゴブリンゾンビ', 'Effect Monster', 'Zombie', 'DARK', 4, 1100, 1050, '①：这张卡给与对方战斗伤害的场合发动。对方卡组最上面的卡送去墓地。 ②：这张卡从场上送去墓地的场合发动。从卡组把1只守备力1200以下的不死族怪兽加入手卡。'),
(71100270, 'Goblin''s Crazy Beast', '格布林的大饕兽', '百鬼羅刹の大饕獣', 'XYZ Monster', 'Fiend', 'DARK', 6, 2700, NULL, '6星怪兽×2只以上 这个卡名的③的效果在决斗中只能使用1次。 ①：自己·对方回合1次，以场上1张魔法·陷阱卡为对象才能发动。场上2个超量素材取除，把作为对象的卡作为这张卡的超量素材。 ②：自己场上的怪兽被效果破坏的场合，可以作为代替把这张卡1个超量素材取除。 ③：这张卡在墓地存在的场合才能发动。这张卡特殊召唤。那之后，可以把自己墓地1只「哥布林」怪兽作为这张卡的超量素材。'),
(11868825, 'Goblin''s Secret Remedy', '哥布林的秘药', 'ゴブリンの秘薬', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己回复600基本分。'),
(25259669, 'Goblindbergh', '格布林德伯格', 'ゴブリンドバーグ', 'Effect Monster', 'Warrior', 'EARTH', 4, 1400, NULL, '①：这张卡召唤时才能发动。从手卡把1只4星以下的怪兽特殊召唤。这张卡是攻击表示的场合，再让这张卡变成守备表示。'),
(83743222, 'Goddess Bow', '女神的圣弓-矢月', '女神の聖弓－アルテミス', 'Fusion Monster', 'Warrior', 'LIGHT', 4, 1500, 1600, '这张卡在用「赫谟之爪」的效果把自己的手卡·场上的战士族怪兽送去墓地的场合才能特殊召唤。 ①：这张卡特殊召唤成功的场合，以这张卡以外的场上1只怪兽为对象发动。这张卡当作装备卡使用给那只怪兽装备。 ②：这张卡的效果让这张卡装备中的场合，自己·对方的战斗阶段中只有1次，对方发动的魔法·陷阱·怪兽的效果无效。这个效果适用的战斗阶段中，装备怪兽可以作2次攻击。'),
(72589042, 'Goddess of Sweet Revenge', '辉煌的逆转之女神', '煌々たる逆転の女神', 'Effect Monster', 'Fairy', 'LIGHT', 6, 1800, 2000, '①：自己场上没有卡存在，自己手卡只有这1张卡的场合，对方怪兽的攻击宣言时把这张卡从手卡丢弃才能发动。对方场上的卡全部破坏。那之后，自己可以从卡组把1只怪兽特殊召唤。'),
(50915474, 'Goddess of the Two Sides', '表里女神', '表裏の女神', 'Effect Monster', 'Fairy', 'LIGHT', 3, 950, 700, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。从卡组把「表里之女神」以外的1只持有进行投掷硬币效果的怪兽加入手卡。 ②：自己主要阶段才能发动。进行1次投掷硬币，对里表作猜测。猜中的场合，自己场上的全部怪兽的攻击力直到回合结束时变成2倍。猜错的场合，自己场上的怪兽全部送去墓地，自己抽1张。'),
(67959180, 'Goddess of Whim', '任性的女神', 'きまぐれの女神', 'Effect Monster', 'Fairy', 'LIGHT', 3, 950, 700, '①：1回合1次，自己主要阶段才能发动。进行1次投掷硬币，对里表作猜测。猜中的场合，这张卡的攻击力直到回合结束时变成2倍。猜错的场合，这张卡的攻击力直到回合结束时变成一半。'),
(38576155, 'Goddess Skuld''s Oracle', '女神诗蔻蒂的托宣', '女神スクルドの託宣', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：作为这张卡的发动时的效果处理，自己场上的怪兽只有「女武神」怪兽的场合，可以从卡组把1张「女神薇儿丹蒂的引导」加入手卡。 ②：1回合1次，自己主要阶段才能发动。从对方卡组上面把3张卡确认，用喜欢的顺序回到卡组上面。这个效果的发动后，直到回合结束时自己不是天使族怪兽不能召唤·特殊召唤。'),
(91969909, 'Goddess Urd''s Verdict', '女神乌尔德的裁断', '女神ウルドの裁断', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：自己场上的「女武神」怪兽不会成为对方的效果的对象，不会被对方的效果破坏。 ②：1回合1次，宣言1个卡名，以对方场上盖放的1张卡为对象才能发动。那张盖放的卡给双方确认，宣言的卡的场合，那张卡除外。不是的场合，选自己场上1张卡除外。'),
(64961254, 'Goddess Verdande''s Guidance', '女神薇儿丹蒂的引导', '女神ヴェルダンディの導き', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：作为这张卡的发动时的效果处理，自己场上的怪兽只有「女武神」怪兽的场合，可以从卡组把1张「女神乌尔德的裁断」加入手卡。 ②：1回合1次，宣言卡的种类（怪兽·魔法·陷阱）才能发动。对方卡组最上面的卡给双方确认，宣言的种类的卡的场合，对方把那张卡在自身场上盖放。不是的场合或者不能盖放的场合，对方把那张卡加入手卡。'),
(53493204, 'Goddess with the Third Eye', '心眼之女神', '心眼の女神', 'Effect Monster', 'Fairy', 'LIGHT', 4, 1200, 1000, '这张卡可以代替融合怪兽素材的其中1只来融合。这个时候，其他的融合素材必须是指定的融合素材。'),
(10236520, 'Goe Goe the Gallant Ninja', '忍者义贼 五卫五卫', '忍者義賊ゴエゴエ', 'Effect Monster', 'Warrior', 'WIND', 4, 1500, 1000, '对方手卡是5张以上的场合，这张卡给与对方基本分战斗伤害时，对方手卡随机丢弃2张。'),
(21155323, 'Goggle Golem', '巨人 果戈尔', '巨人ゴーグル', 'Gemini Monster', 'Rock', 'EARTH', 4, 1500, 500, '这张卡在墓地或者场上表侧表示存在的场合，当作通常怪兽使用。场上表侧表示存在的这张卡可以作当通常召唤使用的再度召唤，这张卡当作效果怪兽使用并得到以下效果。 ●这张卡的原本攻击力变成2100。'),
(39674352, 'Gogiga Gagagigo', '哥吉咖・咖咖吉哥', 'ゴギガ・ガガギゴ', 'Normal Monster', 'Reptile', 'WATER', 8, 2950, 2800, '已经精神崩溃，肉体追求更强的力量而暴走。在它身上再也找不到昔日的面影……'),
(91718579, 'Gogogo Aristera & Dexia', '隆隆隆左手与右手', 'ゴゴゴアリステラ＆デクシア', 'Effect Monster', 'Rock', 'EARTH', 4, NULL, 2200, '①：只要这张卡和这张卡以外的「隆隆隆」怪兽在怪兽区域存在，对方不能选择「隆隆隆」怪兽作为攻击对象，也不能作为效果的对象。 ②：只用包含这张卡的「隆隆隆」怪兽为素材的超量怪兽得到以下效果。 ●这次超量召唤成功时，以对方场上1只表侧攻击表示怪兽为对象才能发动。那只怪兽变成守备表示并把守备力变成0。'),
(56105047, 'Gogogo Ghost', '隆隆隆幽灵', 'ゴゴゴゴースト', 'Effect Monster', 'Zombie', 'DARK', 4, 1900, NULL, '这张卡特殊召唤成功的场合，可以选择自己墓地1只「隆隆隆石人」表侧守备表示特殊召唤。那之后，这张卡变成守备表示。「隆隆隆幽灵」的效果1回合只能使用1次。'),
(39695323, 'Gogogo Giant', '隆隆隆巨人', 'ゴゴゴジャイアント', 'Effect Monster', 'Rock', 'EARTH', 4, 2000, NULL, '①：这张卡召唤成功时，以自己墓地1只「隆隆隆」怪兽为对象才能发动。那只怪兽守备表示特殊召唤。那之后，这张卡变成守备表示。 ②：这张卡攻击的场合，战斗阶段结束时变成守备表示。'),
(19667590, 'Gogogo Gigas', '隆隆隆巨灵', 'ゴゴゴギガース', 'Effect Monster', 'Rock', 'EARTH', 4, NULL, 2200, '这张卡在墓地存在，自己对名字带有「隆隆隆」的怪兽的特殊召唤成功的场合，这张卡可以从墓地表侧守备表示特殊召唤。「隆隆隆巨灵」的效果1回合只能使用1次，这个效果发动的回合，自己不能进行战斗阶段。'),
(35886170, 'Gogogo Goblindbergh', '隆隆隆格布林德伯格', 'ゴゴゴゴブリンドバーグ', 'Effect Monster', 'Warrior', 'EARTH', 4, 1400, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤时才能发动。从自己的手卡·卡组·墓地把1只战士族以外的「隆隆隆」怪兽特殊召唤。这张卡是攻击表示的场合，再让这张卡变成守备表示。这个效果的发动后，直到回合结束时自己不是超量怪兽不能从额外卡组特殊召唤。 ②：超量素材的这张卡为让超量怪兽的效果发动而被取除的场合才能发动。从卡组把1只「怒怒怒」怪兽加入手卡。'),
(62476815, 'Gogogo Golem', '隆隆隆石魔', 'ゴゴゴゴーレム', 'Effect Monster', 'Rock', 'EARTH', 4, 1800, 1500, '①：守备表示的这张卡1回合只有1次不会被战斗破坏。'),
(2948263, 'Gogogo Golem - Golden Form', '隆隆隆石魔－黄金形态', 'ゴゴゴゴーレム－GF', 'Effect Monster', 'Rock', 'EARTH', 4, -1, 1500, '这张卡不能通常召唤。把自己场上1只名字带有「隆隆隆」的怪兽解放的场合才能特殊召唤。这张卡的攻击力变成解放的那只怪兽的原本攻击力2倍的数值。这张卡的战斗发生的对对方的战斗伤害变成一半。此外，1回合1次，对方场上有效果怪兽的效果发动时发动。这张卡的攻击力下降1500，那个效果无效。'),
(59911557, 'Gogogo Goram', '隆隆隆巨魔', 'ゴゴゴゴラム', 'Effect Monster', 'Rock', 'EARTH', 4, 2300, NULL, '这张卡召唤·反转召唤·特殊召唤成功时，这张卡的表示形式变更。场上的这张卡被破坏送去墓地时，从卡组把1只名字带有「隆隆隆」的怪兽送去墓地。'),
(63583431, 'Gogogo Talisman', '隆隆隆护符', 'ゴゴゴ護符', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '自己场上有名字带有「隆隆隆」的怪兽2只以上存在的场合，自己受到的效果伤害变成0。此外，1回合1次，自己场上的名字带有「隆隆隆」的怪兽进行战斗的攻击宣言时才能发动。那只自己怪兽不会被那次战斗破坏。'),
(23116808, 'Goka, the Pyre of Malice', '怨念之魂 业火', '怨念の魂 業火', 'Effect Monster', 'Zombie', 'FIRE', 6, 2200, 1900, '①：自己场上有炎属性怪兽存在的场合，这张卡可以从手卡特殊召唤。 ②：这张卡的①的方法特殊召唤成功的场合，以自己场上1只炎属性怪兽为对象发动。那只自己的炎属性怪兽破坏。 ③：把这张卡以外的自己场上1只炎属性怪兽解放才能发动。这张卡的攻击力直到回合结束时上升500。 ④：自己准备阶段发动。在自己场上把1只「火之玉衍生物」（炎族·炎·1星·攻/守100）守备表示特殊召唤。'),
(15367030, 'Gokibore', '蟑螂球', 'ゴキボール', 'Normal Monster', 'Insect', 'EARTH', 4, 1200, 1400, '圆溜溜的蟑螂。滚来滚去进行攻击。守备想不到还挺强。'),
(17535764, 'Gokipole', '蟑螂柱', 'ゴキポール', 'Effect Monster', 'Insect', 'EARTH', 3, 1000, 1200, '这个卡名的效果1回合只能使用1次。 ①：这张卡被送去墓地的场合才能发动。从卡组把1只4星昆虫族怪兽加入手卡。这个效果把通常怪兽加入的场合，可以再把那只怪兽从手卡特殊召唤。那之后，可以选持有这个效果特殊召唤的怪兽的攻击力以上的攻击力的场上1只怪兽破坏。'),
(14472500, 'Gokipon', '蟑螂宝宝', 'ゴキポン', 'Effect Monster', 'Insect', 'EARTH', 2, 800, 800, '这张卡被战斗破坏送去墓地时，可以从卡组选择1只攻击力1500以下的昆虫族怪兽加入自己手卡。'),
(55010259, 'Gold Gadget', '金色小工具', 'ゴールド・ガジェット', 'Effect Monster', 'Machine', 'LIGHT', 4, 1700, 800, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：这张卡召唤·特殊召唤成功时才能发动。从手卡把1只机械族·4星怪兽特殊召唤。 ②：这张卡被战斗·效果破坏的场合才能发动。从卡组把「金色零件」以外的1只4星「零件」怪兽特殊召唤。'),
(43528009, 'Gold Moon Coin', '星星金币', '星の金貨', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：选自己2张手卡加入对方手卡。那之后，自己从卡组抽2张。'),
(54670997, 'Gold Pride - Better Luck Next Time!', '黄金荣耀－再接再厉', 'GP－ベター・ラック', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张，这个卡名的②的效果1回合只能使用1次。 ①：作为这张卡的发动时的效果处理，以下效果可以适用。 ●从卡组把1只「黄金荣耀」怪兽加入手卡，自己失去那只怪兽的攻击力数值的基本分。 ②：从额外卡组特殊召唤的自己场上的表侧表示的「黄金荣耀」怪兽回到额外卡组的场合才能发动。自己抽1张。'),
(96305350, 'Gold Pride - Captain Carrie', '黄金荣耀－船长卡莉', 'GP－キャプテン・キャリー', 'Effect Monster', 'Fiend', 'WATER', 3, 900, 1700, '这个卡名的①②③的效果1回合各能使用1次。 ①：自己基本分比对方少的场合才能发动。这张卡从手卡特殊召唤。 ②：这张卡召唤·特殊召唤的场合才能发动。从卡组把1张「黄金荣耀」陷阱卡加入手卡。 ③：这张卡被送去墓地的场合，以从额外卡组特殊召唤的自己场上1只「黄金荣耀」怪兽为对象才能发动。从自己墓地把最多3张「黄金荣耀」卡除外，作为对象的怪兽的攻击力上升除外数量×500。'),
(65892585, 'Gold Pride - Chariot Carrie', '黄金荣耀－战车卡莉号', 'GP－チャリオット・キャリー号', 'XYZ Monster', 'Aqua', 'WATER', 3, 1900, 2700, '3星怪兽×2 这个卡名的①的效果1回合只能使用1次。 ①：把这张卡1个超量素材取除才能发动。从卡组把1张「黄金荣耀」魔法卡加入手卡。自己基本分比对方少的场合，可以再从卡组把1只「黄金荣耀」怪兽送去墓地。 ②：这张卡的①的效果发动的回合的结束阶段发动。这张卡回到额外卡组，从自己的卡组·墓地把1只「黄金荣耀-卡丽船长」特殊召唤。'),
(60203670, 'Gold Pride - Eliminator', '黄金荣耀－暗袭手', 'GP－アサシネーター', 'Tuner Monster', 'Machine', 'EARTH', 5, 1800, 800, '这个卡名的①②的效果1回合各能使用1次。 ①：自己基本分比对方少的场合才能发动。这张卡从手卡特殊召唤。 ②：从自己的手卡·场上（表侧表示）·墓地把这张卡以外的1只「黄金荣耀」怪兽除外才能发动。把持有和除外的怪兽的等级相同等级的1只「黄金荣耀衍生物」（机械族·暗·攻/守0）在自己场上特殊召唤。这张卡在这个回合作为融合·同调·超量·连接召唤的素材的场合，不是「黄金荣耀」怪兽的融合·同调·超量·连接召唤不能使用。'),
(45464587, 'Gold Pride - Eradicator', '黄金荣耀－灭击手', 'GP－アニヒレーター', 'Synchro Monster', 'Warrior', 'DARK', 8, 2700, 1700, '调整＋调整以外的怪兽1只以上 这个卡名的①的效果1回合只能使用1次。 ①：对方回合，以场上1只融合·同调·超量·连接怪兽为对象才能发动（自己基本分比对方少的场合，这个效果的对象可以变成2只）。那只怪兽破坏。 ②：这张卡的①的效果发动的回合的结束阶段发动。这张卡回到额外卡组，从自己的卡组·墓地把1只「黄金荣耀-暗杀者」特殊召唤。'),
(90164606, 'Gold Pride - It''s Neck and Neck!', '黄金荣耀－并驾齐驱', 'GP－ネック・アンド・ネック', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：以自己场上1只「黄金荣耀」怪兽或者「黄金荣耀-并驾齐驱」以外的自己墓地1张「黄金荣耀」卡为对象才能发动。那张卡回到手卡。 ②：持有比自己基本分数值高的攻击力的怪兽在对方场上存在的场合，从自己墓地把这张卡和1只「黄金荣耀」怪兽除外才能发动。把有除外的怪兽的卡名记述的1只「黄金荣耀」怪兽从额外卡组特殊召唤。'),
(23512906, 'Gold Pride - Leon', '黄金荣耀－里昂', 'GP－リオン', 'Tuner Monster', 'Warrior', 'WIND', 3, 1500, 1200, '这个卡名的①②③的效果1回合各能使用1次。 ①：自己基本分比对方少的场合才能发动。这张卡从手卡特殊召唤。 ②：这张卡召唤·特殊召唤的场合，以战士族以外的自己墓地1只「黄金荣耀」怪兽为对象才能发动。那只怪兽守备表示特殊召唤。这个效果的发动后，直到回合结束时自己不是「黄金荣耀」怪兽不能从额外卡组特殊召唤。 ③：对方主要阶段才能发动。只用自己场上的「黄金荣耀」怪兽为素材进行同调召唤。'),
(58884063, 'Gold Pride - Nytro Blaster', '黄金荣耀－硝化爆破者', 'GP－Nブラスター', 'Link Monster', 'Pyro', 'DARK', NULL, 2300, NULL, '等级不同的「黄金荣耀」怪兽2只 这个卡名的①的效果1回合只能使用1次。 ①：以对方场上1只怪兽为对象才能发动。那只怪兽破坏。自己基本分比对方少的场合，可以再把在那只怪兽破坏的区域的前面·后面·相邻的区域（怪兽区域·魔法与陷阱区域）存在的卡全部破坏。 ②：这张卡的①的效果发动的回合的结束阶段发动。这张卡回到额外卡组，从自己的卡组·墓地把1只「黄金荣耀-氮氧头领」特殊召唤。'),
(59900655, 'Gold Pride - Nytro Head', '黄金荣耀－硝化头', 'GP－Nヘッド', 'Effect Monster', 'Pyro', 'FIRE', 8, 2300, 2600, '这个卡名的①②③的效果1回合各能使用1次。 ①：自己基本分比对方少的场合才能发动。这张卡从手卡特殊召唤。 ②：对方准备阶段才能发动。在对方场上把1只「氮氧衍生物」（炎族·炎·8星·攻/守0）特殊召唤。这衍生物不能作为连接素材。 ③：对方主要阶段，以场上1只「氮氧衍生物」为对象才能发动。那衍生物以及那些前面·后面·相邻的区域（怪兽区域·魔法与陷阱区域）存在的卡全部破坏。'),
(27275398, 'Gold Pride - Pedal to the Metal!', '黄金荣耀－全速前进', 'GP－ペダル・トゥ・メタル', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：以自己场上1只「黄金荣耀」怪兽为对象才能发动。那只怪兽直到回合结束时攻击力上升500，不会被战斗·效果破坏，不能把效果发动。 ②：这个回合有自己场上的表侧表示的「黄金荣耀」怪兽被战斗·效果破坏的场合，结束阶段才能发动。墓地的这张卡在自己场上盖放。'),
(28497830, 'Gold Pride - Pin Baller', '黄金荣耀－弹球手', 'GP－PB', 'Fusion Monster', 'Machine', 'DARK', 9, 3000, NULL, '「黄金荣耀-滚球手」＋「黄金荣耀」怪兽1只以上 这个卡名的①的效果1回合只能使用1次。 ①：这张卡融合召唤的场合才能发动（自己基本分比对方少的场合，这个效果的发动和效果不会被无效化）。把最多有那个作为融合素材的数量的对方场上的表侧表示怪兽当作装备魔法卡使用给这张卡装备。 ②：这张卡的①的效果发动的回合的结束阶段发动。这张卡回到额外卡组，从自己的卡组·墓地把1只「黄金荣耀-滚球手」特殊召唤。'),
(92003832, 'Gold Pride - Roller Baller', '黄金荣耀－滚球手', 'GP－RB', 'Effect Monster', 'Psychic', 'EARTH', 5, 1800, 1600, '这个卡名的①②的效果1回合各能使用1次。 ①：自己基本分比对方少的场合才能发动。这张卡从手卡特殊召唤。 ②：自己·对方的主要阶段才能发动。自己的手卡·场上的怪兽作为融合素材，把1只「黄金荣耀」融合怪兽融合召唤。'),
(22390469, 'Gold Pride - Star Leon', '黄金荣耀－星之里昂', 'GP－スター・リオン', 'Synchro Monster', 'Thunder', 'LIGHT', 6, 2000, 2000, '调整＋调整以外的怪兽1只以上 这个卡名的①的效果1回合只能使用1次。 ①：自己·对方的主要阶段，以对方场上1只表侧表示怪兽为对象才能发动。这张卡的攻击力上升那只怪兽的原本攻击力数值。自己基本分比对方少的场合，可以再把作为对象的怪兽破坏。 ②：这张卡的①的效果发动的回合的结束阶段发动。这张卡回到额外卡组，从自己的卡组·墓地把1只「黄金荣耀-马狮利昂」特殊召唤。');